def agent(obs, configuration=None):
    step = int(obs.get("step", 0) or 0)
    p = int(obs.get("player", 0) or 0)
    farms = obs.get("farms") or [{}]
    farm = farms[p] if p < len(farms) else {}
    t = TAPE[min(step, len(TAPE) - 1)]
    n = len(farm.get("hands") or [])
    hands = [list(h) for h in (t.get("hands") or [])]
    while len(hands) < n:
        hands.append(["PASS"])
    return {"farmer": list(t.get("farmer") or ["PASS"]), "hands": hands[:n],
            "market": [list(o) for o in (t.get("market") or [])]}


_kaggle_submission_entrypoint = agent
